}

function parseExport(): Stmt {
  advance(); // export
  if (at(T.Fn)) return { kind: "export", stmt: parseFnStmt() };
  if (at(T.Let) || at(T.Const)) return { kind: "export", stmt: parseLetStmt() };
  throw new Error(`Expected fn or let after export at line ${peek().line}`);
}

