  } else if (stmt.kind === 'struct') {
    console.log(`📌 구조체: ${stmt.name}`);
    if (stmt.typeParams) {
      console.log(`   제네릭: <${stmt.typeParams.join(', ')}>`);
    }
    console.log();
  } else if (stmt.kind === 'enum') {
    console.log(`📌 Enum: ${stmt.name}`);
    if (stmt.typeParams) {
      console.log(`   제네릭: <${stmt.typeParams.join(', ')}>`);
    }
    console.log();
