   785→// Helper for value equality check
   786→function valEq(a: Value, b: Value): boolean {
   787→  if (a.tag !== b.tag) return false;
   788→  if (a.tag === "null") return true;
   789→  if (a.tag === "num" || a.tag === "str" || a.tag === "bool") return (a as any).val === (b as any).val;
   790→  return a === b;
   791→}
   792→
   793→// Helpers
   794→function numVal(v: Value): number { return v.tag === "num" ? v.val : 0; }
   795→function strVal(v: Value): string { return v.tag === "str" ? v.val : String((v as any).val ?? ""); }
   796→function truthy(v: Value): boolean {
   797→  if (v.tag === "null") return false;
   798→  if (v.tag === "bool") return v.val;
   799→  if (v.tag === "num") return v.val !== 0;
   800→  if (v.tag === "str") return v.val !== "";
   801→  return true;
   802→}
   803→
   804→function toJS(v: Value): any {
   805→  switch (v.tag) {
   806→    case "num": case "str": case "bool": return v.val;
   807→    case "null": return null;
   808→    case "array": return v.val.map(toJS);
   809→    case "object": {
   810→      const obj: any = {};
   811→      for (const [k, val] of v.val) obj[k] = toJS(val);
   812→      return obj;
   813→    }
   814→    default: return null;
   815→  }
   816→}
   817→
   818→function fromJS(v: any): Value {
   819→  if (v === null || v === undefined) return { tag: "null" };
   820→  if (typeof v === "number") return { tag: "num", val: v };
   821→  if (typeof v === "string") return { tag: "str", val: v };
   822→  if (typeof v === "boolean") return { tag: "bool", val: v };
   823→  if (Array.isArray(v)) return { tag: "array", val: v.map(fromJS) };
   824→  if (typeof v === "object") {
   825→    const map = new Map<string, Value>();
   826→    for (const [k, val] of Object.entries(v)) map.set(k, fromJS(val));
   827→    return { tag: "object", val: map };
   828→  }
   829→  return { tag: "null" };
   830→}
