    decls.push(`} ${enumName}_Tag;`);

    // 2. Union 정의 (각 variant의 필드)
    decls.push(`typedef union {`);
    for (const variant of info.variants) {
      if (variant.fields.length > 0) {
        decls.push(`  struct {`);
