     3→import { Expr, Stmt, Program } from "../ast";
     4→
     5→export class CCodegen {
     6→  private lines: string[] = [];
     7→  private indent = 0;
     8→  private tempCounter = 0;
     9→
    10→  generate(program: Program): string {
    11→    // 헤더
    12→    this.emitLine('#include "fl_runtime.h"');
    13→    this.emitLine("");
    14→
    15→    // 함수 선언들
    16→    const topLevelStmts = [];
    17→    for (const stmt of program.stmts) {
    18→      if (stmt.kind === "fn") {
    19→        this.declareFn(stmt as any);
    20→      } else {
    21→        topLevelStmts.push(stmt);
    22→      }
    23→    }
    24→    this.emitLine("");
    25→
    26→    // 함수 정의
    27→    for (const stmt of program.stmts) {
    28→      if (stmt.kind === "fn") {
    29→        this.genStmt(stmt);
    30→        this.emitLine("");
    31→      }
    32→    }
    33→
    34→    // main 함수 (top-level statements 포함)
    35→    this.emitLine("int main(int argc, char **argv) {");
    36→    this.indent++;
    37→    if (topLevelStmts.length === 0) {
    38→      this.emitLine("return 0;");
    39→    } else {
    40→      for (const stmt of topLevelStmts) {
    41→        this.genStmt(stmt);
    42→      }
    43→      this.emitLine("return 0;");
    44→    }
    45→    this.indent--;
    46→    this.emitLine("}");
    47→
    48→    return this.lines.join("\n");
    49→  }
    50→
    51→  private emit(text: string) {
    52→    this.lines.push("  ".repeat(this.indent) + text);
    53→  }
    54→
    55→  private emitLine(text: string) {
    56→    this.lines.push(text);
    57→  }
    58→
    59→  private tempVar(): string {
    60→    return `__tmp${this.tempCounter++}`;
    61→  }
    62→
    63→  private declareFn(stmt: any) {
    64→    const name = stmt.name;
    65→    this.emit(`fl_value* fl_${name}(fl_value **args, int arg_count);`);
    66→  }
    67→
    68→  private genStmt(stmt: Stmt) {
    69→    switch (stmt.kind) {
    70→      case "fn": {
    71→        const s = stmt as any;
    72→        this.emit(`fl_value* fl_${s.name}(fl_value **args, int arg_count) {`);
    73→        this.indent++;
    74→        if (s.body.length === 0) {
    75→          this.emit("return fl_null();");
    76→        } else {
    77→          for (const b of s.body) {
    78→            this.genStmt(b);
    79→          }
    80→        }
    81→        this.indent--;
    82→        this.emit("}");
    83→        break;
    84→      }
    85→
    86→      case "let": {
    87→        const s = stmt as any;
    88→        if (s.init) {
    89→          const exprCode = this.genExpr(s.init);
    90→          this.emit(`fl_value *${s.name} = ${exprCode};`);
    91→        } else {
    92→          this.emit(`fl_value *${s.name} = fl_null();`);
    93→        }
    94→        break;
    95→      }
    96→
    97→      case "return": {
    98→        const s = stmt as any;
    99→        if (s.value) {
   100→          const exprCode = this.genExpr(s.value);
   101→          this.emit(`return ${exprCode};`);
   102→        } else {
   103→          this.emit("return fl_null();");
   104→        }
   105→        break;
   106→      }
   107→
   108→      case "print": {
   109→        const s = stmt as any;
   110→        const exprCode = this.genExpr(s.expr);
   111→        const fn = s.newline ? "fl_println" : "fl_print";
   112→        this.emit(`${fn}(${exprCode});`);
   113→        break;
   114→      }
   115→
   116→      case "expr": {
   117→        const s = stmt as any;
   118→        const exprCode = this.genExpr(s.expr);
   119→        this.emit(`${exprCode};`);
