   121→      }
   122→
   123→      case "if": {
   124→        const s = stmt as any;
   125→        const cond = this.genExpr(s.cond);
   126→        this.emit(`if (fl_is_truthy(${cond})) {`);
   127→        this.indent++;
   128→        for (const b of s.then) {
