   240→   * Supports: let x = match value { ... };
   241→   * Returns an Expr with kind "match"
   242→   */
   243→  function parseMatchExpr(): Expr {
   244→    advance(); // match
   245→    const subject = parseExpr();
   246→    expect(T.LBrace);
   247→    const arms: MatchArm[] = [];
   248→
   249→    while (!at(T.RBrace) && !at(T.EOF)) {
   250→      let pattern: Expr | null = null;
   251→      if (at(T.Ident) && peek().value === "_") {
   252→        advance(); // _
   253→      } else {
   254→        pattern = parseExpr();
   255→      }
   256→
   257→      // Parse optional guard clause: if condition
   258→      let guard: Expr | null = null;
   259→      if (match(T.If)) {
   260→        guard = parseExpr();
   261→      }
   262→
   263→      expect(T.FatArrow, "Expected '=>' in match arm");
   264→
   265→      // Parse body: can be expr or block
   266→      let body: Stmt[];
   267→      if (at(T.LBrace)) {
   268→        expect(T.LBrace);
   269→        body = parseBody();
   270→        expect(T.RBrace);
   271→      } else {
   272→        // Single expression as body
   273→        const expr = parseExpr();
   274→        body = [{ kind: "expr", expr }];
   275→      }
   276→
   277→      arms.push({ pattern, guard, body });
   278→      match(T.Comma);
   279→    }
   280→
   281→    expect(T.RBrace);
   282→    return { kind: "match", subject, arms } as any;
   283→  }
   284→
   285→  function parseWhile(): Stmt {
   286→    advance(); // while
   287→
   288→    // Check for while let pattern
   289→    if (at(T.Let)) {
   290→      return parseWhileLet();
   291→    }
   292→
   293→    const useParen = match(T.LParen);
   294→    const cond = parseExpr();
   295→    if (useParen) expect(T.RParen);
   296→    expect(T.LBrace);
   297→    const body = parseBody();
   298→    expect(T.RBrace);
   299→    return { kind: "while", cond, body };
   300→  }
   301→
   302→  function parseWhileLet(): Stmt {
   303→    advance(); // let
   304→    const pattern = parseOr(); // Use parseOr to avoid consuming the = operator
   305→    expect(T.Assign);
   306→    const value = parseOr(); // Use parseOr for consistency
   307→    expect(T.LBrace);
   308→    const body = parseBody();
   309→    expect(T.RBrace);
   310→
   311→    return { kind: "while-let", pattern, value, body };
   312→  }
   313→
   314→  function parseFor(): Stmt {
   315→    advance(); // for
   316→    const name = expect(T.Ident, "Expected loop variable").value;
   317→    expect(T.In, "Expected 'in'");
   318→    const iter = parseExpr();
   319→    expect(T.LBrace);
   320→    const body = parseBody();
   321→    expect(T.RBrace);
   322→    return { kind: "for", name, iter, body };
   323→  }
