fl_value* fl_add(fl_value **args, int arg_count);

fl_value* fl_add(fl_value **args, int arg_count) {
  return fl_add(a, b);
}

int main(int argc, char **argv) {
  fl_println(fl_string("Test 1: Basic printing"));
  fl_println(fl_string("Hello, FreeLang!"));
  fl_println(fl_string(""));
  fl_println(fl_string("Test 2: Variables"));
  fl_value *x = fl_int(42);
  fl_println(fl_add(fl_string("x = "), x));
  fl_println(fl_string(""));
  fl_println(fl_string("Test 3: Arrays"));
  fl_value *__tmp0 = fl_array_new();
  fl_array_push(__tmp0, fl_int(1));
  fl_array_push(__tmp0, fl_int(2));
  fl_array_push(__tmp0, fl_int(3));
  fl_array_push(__tmp0, fl_int(4));
  fl_array_push(__tmp0, fl_int(5));
  fl_value *arr = __tmp0;
  fl_println(fl_add(fl_string("Array length: "), fl_struct_get_field(arr, "length")));
