          for (const stmt of arm.body) {
            if (stmt.kind === "expr") {
              const exprCode = this.genExpr((stmt as any).expr);
              this.emit(`${tmp} = ${exprCode};`);
            } else {
              this.genStmt(stmt);
            }
          }

          this.emit(`break;`);
          this.indent--;
          this.emit(`}`);
        }

        this.indent--;
        this.emit(`}`);
        this.indent--;
        this.emit(`})`);

        return tmp;
      }

      default:
        return "fl_null()";
    }
  }
}

