    bindingNames = (pattern as any).args.map((a: any) => a.name);
  } else {
    throw new Error(`Invalid pattern in match: expected EnumName.Variant or EnumName.Variant(...)`);
  }

  const variantInfo = enumInfo.variants.get(variantName);

