#include "fl_runtime.h"

typedef struct Result Result;
typedef struct Option Option;
typedef struct Tree Tree;

struct Result {
  int tag;
  union {
    struct {
      fl_value *i32;
    } Ok;
    struct {
      fl_value *string;
    } Err;
  } data;
};

struct Result* Result_Ok(fl_value *i32);
struct Result* Result_Err(fl_value *string);

struct Option {
  int tag;
  union {
    struct {
      fl_value *i32;
    } Some;
  } data;
};

