  if (a->type != 1 || b->type != 1) return fl_string("");

  size_t len_a = strlen(a->data.str);
  size_t len_b = strlen(b->data.str);
  char *result = (char*)malloc(len_a + len_b + 1);

  strcpy(result, a->data.str);
  strcat(result, b->data.str);

  fl_value *v = (fl_value*)malloc(sizeof(fl_value));
  v->data.str = result;
  v->type = 1;
  return v;
}

fl_value* fl_string_char_at(fl_value *s, fl_value *idx) {
  if (s->type != 1) return fl_int(0);

  int i = (int)idx->data.i;
  int len = (int)strlen(s->data.str);

  if (i < 0 || i >= len) return fl_int(0);
  return fl_int((long long)(unsigned char)s->data.str[i]);
}

fl_value* fl_string_substring(fl_value *s, fl_value *start, fl_value *len) {
  if (s->type != 1) return fl_string("");

  int st = (int)start->data.i;
  int l = (int)len->data.i;
  int slen = (int)strlen(s->data.str);

  if (st < 0 || st >= slen || l < 0) return fl_string("");
  if (st + l > slen) l = slen - st;

  char *result = (char*)malloc(l + 1);
  strncpy(result, s->data.str + st, l);
  result[l] = '\0';

  fl_value *v = (fl_value*)malloc(sizeof(fl_value));
  v->data.str = result;
  v->type = 1;
  return v;
}

fl_value* fl_string_equals(fl_value *a, fl_value *b) {
  if (a->type != 1 || b->type != 1) return fl_int(0);
  return fl_int(strcmp(a->data.str, b->data.str) == 0);
}

fl_value* fl_string_contains(fl_value *s, fl_value *substr) {
  if (s->type != 1 || substr->type != 1) return fl_int(0);
  return fl_int(strstr(s->data.str, substr->data.str) != NULL);
}

fl_value* fl_string_index_of(fl_value *s, fl_value *substr) {
  if (s->type != 1 || substr->type != 1) return fl_int(-1);

  char *pos = strstr(s->data.str, substr->data.str);
  if (pos == NULL) return fl_int(-1);

  return fl_int((long long)(pos - s->data.str));
}

// ========================================
