// ========================================

fl_value* fl_is_digit(fl_value *c) {
  int ch = (int)c->data.i;
  return fl_int(ch >= 48 && ch <= 57);  // '0' = 48, '9' = 57
}

fl_value* fl_is_alpha(fl_value *c) {
  int ch = (int)c->data.i;
  // 'a'-'z' = 97-122, 'A'-'Z' = 65-90
  return fl_int((ch >= 97 && ch <= 122) || (ch >= 65 && ch <= 90));
}

fl_value* fl_is_whitespace(fl_value *c) {
  int ch = (int)c->data.i;
  // space=32, tab=9, newline=10, carriage return=13
  return fl_int(ch == 32 || ch == 9 || ch == 10 || ch == 13);
}

fl_value* fl_to_upper(fl_value *c) {
  int ch = (int)c->data.i;
  if (ch >= 97 && ch <= 122) {  // lowercase
    return fl_int(ch - 32);  // convert to uppercase
  }
