  return fl_int(b->data.i != 0 ? a->data.i % b->data.i : 0);
}

fl_value* fl_eq(fl_value *a, fl_value *b) {
  if (a->type == 1 && b->type == 1) {  // both strings
    return fl_int(strcmp(a->data.str, b->data.str) == 0);
  }
  return fl_int(a->data.i == b->data.i);
}

fl_value* fl_neq(fl_value *a, fl_value *b) {
  if (a->type == 1 && b->type == 1) {  // both strings
