  if is_upper(c) {
    c + 32  // ASCII 'A'=65 → 'a'=97
  } else {
    c
  }
}

fn to_upper(c) {
  if is_lower(c) {
    c - 32  // ASCII 'a'=97 → 'A'=65
  } else {
    c
  }
