// Phase 6-2: Array & Dynamic Memory Test
// 목표: List 기반 배열 구현 및 동적 메모리 관리 검증

// 기본 List 타입 (정수 목록)
enum List {
  Nil,
  Cons(i32, List)
}

// 배열 기본 연산

// array_length: List의 길이 계산
fn array_length(arr) {
  match arr {
    List.Nil => 0,
    List.Cons(head, tail) => 1 + array_length(tail)
  }
}

// array_sum: List의 모든 요소 합산
fn array_sum(arr) {
  match arr {
    List.Nil => 0,
    List.Cons(head, tail) => head + array_sum(tail)
  }
}

// array_first: 첫 번째 요소 가져오기
fn array_first(arr) {
  match arr {
    List.Nil => 0,
    List.Cons(head, tail) => head
  }
}

// array_last: 마지막 요소 가져오기
fn array_last(arr) {
  match arr {
    List.Nil => 0,
    List.Cons(head, tail) => {
      let rest = array_last(tail)
      if array_length(tail) == 0 {
        head
      } else {
        rest
      }
    }
  }
}

// array_get: 특정 인덱스의 요소 가져오기
fn array_get(arr, idx) {
  if idx < 0 {
    0
  } else {
    match arr {
      List.Nil => 0,
      List.Cons(head, tail) => {
        if idx == 0 {
          head
        } else {
          array_get(tail, idx - 1)
        }
      }
    }
  }
}

// array_reverse: List 반전
fn array_reverse(arr) {
  // Helper: reverse_helper(List, accumulator)
  fn reverse_helper(lst, acc) {
    match lst {
      List.Nil => acc,
      List.Cons(head, tail) => {
        reverse_helper(tail, List.Cons(head, acc))
      }
    }
  }

  reverse_helper(arr, List.Nil)
}

// 테스트 1: 배열 길이 계산
